 if p.exists():
  if p.is_symlink() or p.read_bytes()!=body:raise RuntimeError("Preserve existing record: "+str(p))
  return
 part=p.with_name("."+p.name+"."+uuid.uuid4().hex+".part")
 try:
  with part.open("xb") as out:out.write(body);out.flush();os.fsync(out.fileno())
  try:os.link(part,p)
  except FileExistsError:
   if p.read_bytes()!=body:raise RuntimeError("Conflicting original record")
 finally:
  if part.exists():part.unlink()
